package core

import (
	"bytes"
	"os"
	"testing"

	"github.com/hdt3213/rdb/model"
)

// TestParseRedis8RDB verifies RDB version 13 generated by Redis 8.6, including
// the new stream type 26 (STREAM_LISTPACKS_4) and its IDMP metadata.
func TestParseRedis8RDB(t *testing.T) {
	f, err := os.Open("testdata/redis8.rdb")
	if err != nil {
		t.Fatalf("open fixture: %v", err)
	}
	defer f.Close()

	types := map[string]int{}
	var streams []*model.StreamObject
	dec := NewDecoder(f)
	if err := dec.Parse(func(object model.RedisObject) bool {
		types[object.GetType()]++
		if stream, ok := object.(*model.StreamObject); ok {
			streams = append(streams, stream)
		}
		return true
	}); err != nil {
		t.Fatalf("parse Redis 8 RDB: %v", err)
	}

	for _, typ := range []string{
		model.StringType,
		model.HashType,
		model.ListType,
		model.SetType,
		model.ZSetType,
		model.StreamType,
	} {
		if types[typ] == 0 {
			t.Errorf("missing object type %q in parsed RDB", typ)
		}
	}
	if len(streams) != 2 {
		t.Fatalf("stream count = %d, want 2", len(streams))
	}
	for _, stream := range streams {
		if stream.Version != 4 {
			t.Errorf("stream %q version = %d, want 4", stream.GetKey(), stream.Version)
		}
		if stream.Length == 0 {
			t.Errorf("stream %q has zero length", stream.GetKey())
		}
		if stream.GetElemCount() == 0 {
			t.Errorf("stream %q has zero element count", stream.GetKey())
		}
		if stream.GetKey() == "fork:idmp" && stream.IIDsAdded == 0 {
			t.Errorf("stream %q has zero IIDsAdded, IDMP metadata was not consumed", stream.GetKey())
		}
	}
}

func TestParseRedis8MetadataOpcodes(t *testing.T) {
	cases := []struct {
		name string
		meta []byte
	}{
		{name: "slot-info", meta: []byte{244, 0, 0, 0}},
		{name: "key-meta-empty", meta: []byte{243, 0}},
		{name: "key-meta-module", meta: []byte{243, 1, 1, 2, 3, 4, 0}},
		{name: "combined", meta: []byte{244, 0, 0, 0, 243, 1, 1, 2, 3, 4, 0}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			buf := append([]byte("REDIS0013"), tc.meta...)
			buf = append(buf, 0, 1, 'k', 1, 'v', 255)
			buf = append(buf, make([]byte, 8)...)

			var objects int
			dec := NewDecoder(bytes.NewReader(buf))
			if err := dec.Parse(func(object model.RedisObject) bool {
				objects++
				if object.GetKey() != "k" {
					t.Errorf("key = %q, want k", object.GetKey())
				}
				return true
			}); err != nil {
				t.Fatalf("parse: %v", err)
			}
			if objects != 1 {
				t.Errorf("objects = %d, want 1", objects)
			}
		})
	}
}
